class ToolDispatcher:

    def __init__(self, db: AsyncSession):
        self.db = db

    async def call_tool(self, tool_name: str, arguments: dict) -> Any:
        """Execute a tool and return structured results."""
        log = logger.bind(tool=tool_name, args_keys=list(arguments.keys()))

        try:
            handler = getattr(self, f"_handle_{tool_name}", None)
            if not handler:
                return {"error": f"Unknown tool: {tool_name}"}
            result = await handler(arguments)
            log.info("tool_executed_ok")
            return result
        except KeyError as e:
            log.error("tool_execution_failed", error=f"Missing parameter: {e}")
            return {"error": f"Missing required parameter: {e}"}
        except Exception as e:
            error_msg = str(e) or f"{type(e).__name__}: LLM API timeout — try again"
            log.error("tool_execution_failed", error=error_msg)
            return {"error": error_msg}

    # ─── Tool Handlers ────────────────────────────────────────────

    async def _handle_search_papers(self, args: dict) -> dict:
        from app.services.search.instances import hybrid_service

        query = args["query"]
        limit = args.get("limit", 10)
        results = hybrid_service.search(
            query=query,
            mode=args.get("mode", "hybrid"),
            per_page=limit,
        )

        # Supplement with OpenAlex when local results are sparse
        local_count = len(results.get("results", []))
        if local_count < limit:
            try:
                from app.clients.openalex import OpenAlexClient
                oa = OpenAlexClient(mailto="kaleidoscope@research.app")
                try:
                    needed = limit - local_count
                    oa_results = await oa.search_works(query, rows=needed)
                    external = []
                    for work in oa_results:
                        title = work.get("title", "")
                        if not title:
                            continue
                        abstract_inv = work.get("abstract_inverted_index")
                        abstract = ""
                        if abstract_inv and isinstance(abstract_inv, dict):
                            words = sorted(
                                ((pos, word) for word, positions in abstract_inv.items() for pos in positions),
                                key=lambda x: x[0]
                            )
                            abstract = " ".join(w for _, w in words)[:300]
                        external.append({
                            "title": title,
                            "abstract": abstract,
                            "doi": work.get("doi", "").replace("https://doi.org/", "") if work.get("doi") else None,
                            "year": work.get("publication_year"),
                            "citation_count": work.get("cited_by_count", 0),
                            "source": "openalex",
                        })
                    if external:
                        results["results_external"] = external
                finally:
                    await oa.close()
            except Exception:
                pass

        # Auto-record to dossier if dossier_id provided
        if args.get("dossier_id"):
            try:
                await self._dossier_record_search(args["dossier_id"], query, results)
            except Exception:
                pass

        return results

    async def _dossier_record_search(self, dossier_id: str, query: str, results: dict):
        """Record search results into a dossier (fire-and-forget helper)."""
        import json as _json
        from datetime import datetime, timezone
        from sqlalchemy import text

        now = datetime.now(timezone.utc).isoformat()

        row = await self.db.execute(text(
            "SELECT papers_seen, memory_log FROM research_dossiers WHERE id = :id AND deleted_at IS NULL"
        ), {"id": dossier_id})
        data = row.fetchone()
        if not data:
            return

        papers_seen = data[0] or {}
        memory_log = data[1] or []

        # Record papers from results (hybrid search uses "hits" key)
        new_papers = 0
        for paper in (results.get("hits", []) or results.get("results", []))[:10]:
            pid = paper.get("paper_id", paper.get("id", paper.get("title", "")))
            if pid and pid not in papers_seen:
                papers_seen[pid] = {
                    "title": paper.get("title", ""),
                    "relevance": "search_result",
                    "notes": f"Found via search: {query}",
                    "added_at": now,
                }
                new_papers += 1

        if new_papers > 0:
            memory_log.append({
                "action": "auto_search_record",
                "query": query,
                "papers_added": new_papers,
                "timestamp": now,
            })

            await self.db.execute(text("""
                UPDATE research_dossiers SET
                    papers_seen = CAST(:papers AS jsonb),
                    memory_log = CAST(:log AS jsonb),
                    updated_at = NOW()
                WHERE id = :id
            """), {
                "id": dossier_id,
                "papers": _json.dumps(papers_seen),
                "log": _json.dumps(memory_log[-100:]),
            })
            await self.db.commit()

    async def _handle_get_paper(self, args: dict) -> dict:
        from app.services.collection_service import ReadingStatusService

        identifier = args["identifier"]
        # Try UUID, DOI, arXiv ID
        query = select(Paper).where(Paper.deleted_at.is_(None))
        if len(identifier) == 36 and "-" in identifier:  # UUID
            query = query.where(Paper.id == identifier)
        elif identifier.startswith("10."):  # DOI
            query = query.where(Paper.doi == identifier)
        else:  # arXiv ID
            query = query.where(Paper.arxiv_id == identifier)

        result = await self.db.execute(query)
        paper = result.scalar_one_or_none()
        if not paper:
            return {"error": "Paper not found"}

        # Get per-user reading status from UserReadingStatus table
        rs_svc = ReadingStatusService(self.db)
        reading_status = await rs_svc.get_status(str(paper.id))

        return {
            "id": str(paper.id),
            "doi": paper.doi,
            "arxiv_id": paper.arxiv_id,
            "title": paper.title,
            "abstract": paper.abstract,
            "published_at": str(paper.published_at) if paper.published_at else None,
            "citation_count": paper.citation_count,
            "has_full_text": paper.has_full_text,
            "reading_status": reading_status,
        }

    async def _handle_get_citations(self, args: dict) -> dict:
        from app.services.graph.citation_graph import CitationGraphService

        paper_id = args["paper_id"]
        direction = args.get("direction", "both")
        limit = args.get("limit", 20)

        svc = CitationGraphService(self.db)
        result = await svc.get_citations(paper_id, direction=direction, limit=limit)

        # Always enrich with OpenAlex when paper has a DOI — local refs are mostly unresolved
        forward = result.get("forward_citations", [])
        backward = result.get("backward_citations", [])
        resolved_backward = sum(1 for b in backward if b.get("resolved"))

        try:
            paper_row = await self.db.execute(
                select(Paper.doi, Paper.arxiv_id).where(Paper.id == paper_id)
            )
            paper = paper_row.one_or_none()
            if paper and paper.doi:
                from app.clients.openalex import OpenAlexClient
                oa = OpenAlexClient(mailto="kaleidoscope@research.app")
                try:
                    work = await oa.get_work_by_doi(paper.doi)
                    if work and work.get("id"):
                        openalex_id = work["id"].split("/")[-1]
                        result["openalex_id"] = openalex_id
                        result["openalex_cited_by_count"] = work.get("cited_by_count", 0)

                        if direction in ("forward", "both"):
                            citations = await oa.get_citations(openalex_id, per_page=limit)
                            external_forward = []
                            for c in citations:
                                if c.get("title"):
                                    authors = [a.get("author", {}).get("display_name", "") for a in c.get("authorships", [])[:3]]
                                    external_forward.append({
                                        "title": c["title"],
                                        "year": c.get("publication_year"),
                                        "citation_count": c.get("cited_by_count", 0),
                                        "authors": authors,
                                        "doi": c.get("doi", "").replace("https://doi.org/", "") if c.get("doi") else None,
                                        "source": "openalex",
                                    })
                            if external_forward:
                                result["forward_citations_external"] = external_forward

                        if direction in ("backward", "both"):
                            refs = await oa.get_references(openalex_id, per_page=limit)
                            external_backward = []
                            for ref in refs:
                                if ref.get("title"):
                                    external_backward.append({
                                        "title": ref["title"],
                                        "year": ref.get("publication_year"),
                                        "citation_count": ref.get("cited_by_count", 0),
                                        "doi": ref.get("doi", "").replace("https://doi.org/", "") if ref.get("doi") else None,
                                        "source": "openalex",
                                    })
                            if external_backward:
                                result["backward_citations_external"] = external_backward
                finally:
                    await oa.close()
        except Exception:
            pass

        return result

