    async def _handle_extract_methodology(self, args: dict) -> dict:
        from app.clients.llm_client import DEFAULT_CHAT_MODEL, LLMClient
        from app.services.extraction.chunker import TextChunker

        result = await self.db.execute(
            select(Paper).where(Paper.id == args["paper_id"])
        )
        paper = result.scalar_one_or_none()
        if not paper:
            return {"error": "Paper not found"}

        fulltext = TextChunker.prepare_paper_text(paper)
        has_full_text = len(fulltext.split()) > 300

        if has_full_text:
            from app.services.extraction.extractor import ExtractionService
            svc = ExtractionService(self.db)
            try:
                methods = await svc.extract_methods(paper)
                if args.get("focus"):
                    from app.services.extraction.qa_engine import PaperQAEngine
                    qa = PaperQAEngine(self.db)
                    try:
                        focus_result = await qa.ask(
                            args["paper_id"],
                            f"Describe the {args['focus']} in detail: specific techniques, parameters, and design choices.",
                        )
                        methods["focused_extraction"] = {
                            "focus": args["focus"],
                            "details": focus_result.to_dict(),
                        }
                    finally:
                        await qa.close()
                return methods
            except Exception:
                pass
            finally:
                await svc.close()

        context = f"Title: {paper.title}\nAbstract: {paper.abstract or ''}\n"
        if hasattr(paper, "deep_analysis") and paper.deep_analysis and isinstance(paper.deep_analysis, dict):
            da = paper.deep_analysis
            for key in ["methodology", "contributions", "key_findings"]:
                if da.get(key):
                    val = da[key]
                    if isinstance(val, list):
                        context += f"\n{key}: " + "; ".join(str(v) for v in val)
                    else:
                        context += f"\n{key}: {val}"

        llm = LLMClient()
        try:
            response = await llm.complete(
                prompt=(
                    f"Extract methods, datasets, and metrics from this paper.\n\n{context}\n\n"
                    "Return JSON:\n"
                    '{"methods": [{"name": "...", "description": "...", "is_novel": true/false}], '
                    '"datasets": [{"name": "...", "size": "...", "domain": "..."}], '
                    '"metrics": [{"name": "...", "value": "...", "is_main_result": true/false}], '
                    '"baselines": ["..."], '
                    '"implementation_details": {"framework": "...", "hardware": "...", "code_available": false}}\n\n'
                    "Extract everything mentioned, even if details are sparse. "
                    "If a field is not mentioned, use an empty list."
                ),
                system="You are an expert academic paper analyzer. Return valid JSON only.",
                model=DEFAULT_CHAT_MODEL,
                max_tokens=3000,
                temperature=0.1,
            )
            methods = self._extract_json(response)
            if not methods or not isinstance(methods, dict):
                methods = {"methods": [], "datasets": [], "metrics": [], "baselines": []}
            methods["note"] = "Extracted from abstract/metadata (full text not available)"
            return methods
        finally:
            await llm.close()

