    async def _handle_find_reading_path(self, args: dict) -> dict:
        from app.services.intelligence_service import IntelligenceService

        paper_id = args["paper_id"]
        max_papers = args.get("max_papers", 10)

        svc = IntelligenceService(self.db)
        reading_order = await svc.get_reading_order(
            paper_id=paper_id,
            max_papers=max_papers,
        )
        prereqs = await svc.get_prerequisites(
            paper_id=paper_id,
            top_k=max_papers,
        )

        # If citation graph is sparse, use resolved references from paper_references
        if len(reading_order) <= 1 and len(prereqs) == 0:
            from sqlalchemy import text as sa_text
            result = await self.db.execute(select(Paper).where(Paper.id == paper_id))
            paper = result.scalar_one_or_none()
            if paper:
                # Try resolved references first (papers this one cites that are in our DB)
                ref_result = await self.db.execute(sa_text("""
                    SELECT p.id, p.title, p.doi, p.published_at, p.citation_count
                    FROM paper_references pr
                    JOIN papers p ON p.id = pr.cited_paper_id
                    WHERE pr.citing_paper_id = :paper_id
                      AND pr.cited_paper_id IS NOT NULL
                      AND p.deleted_at IS NULL
                    ORDER BY p.citation_count DESC NULLS LAST
                    LIMIT :limit
                """), {"paper_id": str(paper_id), "limit": max_papers})
                cited_papers = ref_result.all()

                # Also check papers that cite this one (forward citations)
                if not cited_papers:
                    fwd_result = await self.db.execute(sa_text("""
                        SELECT p.id, p.title, p.doi, p.published_at, p.citation_count
                        FROM paper_references pr
                        JOIN papers p ON p.id = pr.citing_paper_id
                        WHERE pr.cited_paper_id = :paper_id
                          AND p.deleted_at IS NULL
                        ORDER BY p.published_at DESC NULLS LAST
                        LIMIT :limit
                    """), {"paper_id": str(paper_id), "limit": max_papers})
                    citing_papers = fwd_result.all()
                    if citing_papers:
                        cited_papers = citing_papers

                if cited_papers:
                    reading_order = []
                    for i, p in enumerate(cited_papers):
                        reading_order.append({
                            "id": str(p[0]),
                            "title": p[1],
                            "doi": p[2],
                            "published_at": str(p[3]) if p[3] else None,
                            "depth": i,
                            "is_root": False,
                            "role": "cited_reference",
                        })
                    reading_order.append({
                        "id": str(paper.id),
                        "title": paper.title,
                        "doi": paper.doi,
                        "published_at": str(paper.published_at) if paper.published_at else None,
                        "depth": len(reading_order),
                        "is_root": True,
                        "role": "target",
                    })
                    prereqs = [
                        {"id": str(p[0]), "title": p[1], "reason": "directly cited by target paper"}
                        for p in cited_papers[:5]
                    ]
                else:
                    # Fall back to semantic similarity
                    try:
                        from app.services.search.instances import vector_service
                        query_text = paper.title
                        if paper.abstract:
                            query_text += " " + paper.abstract[:300]
                        vec_results = vector_service.search(query_text, top_k=max_papers * 2)

                        similar_ids = [
                            hit["paper_id"] for hit in vec_results
                            if hit.get("paper_id") and hit["paper_id"] != str(paper_id)
                        ][:max_papers * 2]

                        if similar_ids:
                            stmt = (
                                select(Paper.id, Paper.title, Paper.doi, Paper.published_at, Paper.citation_count)
                                .where(Paper.id.in_(similar_ids), Paper.deleted_at.is_(None))
                            )
                            result = await self.db.execute(stmt)
                            similar_papers = list(result.all())

                            target_date = paper.published_at
                            foundational = [
                                p for p in similar_papers
                                if p.published_at and target_date and p.published_at < target_date
                            ]
                            if not foundational:
                                foundational = [
                                    p for p in similar_papers
                                    if str(p.id) != str(paper_id)
                                ]
                            foundational.sort(key=lambda p: p.citation_count or 0, reverse=True)

                            reading_order = []
                            for i, p in enumerate(foundational[:max_papers - 1]):
                                is_older = p.published_at and target_date and p.published_at < target_date
                                reading_order.append({
                                    "id": str(p.id),
                                    "title": p.title,
                                    "doi": p.doi,
                                    "published_at": str(p.published_at) if p.published_at else None,
                                    "depth": i,
                                    "is_root": False,
                                    "role": "foundational" if is_older else "background",
                                })
                            reading_order.append({
                                "id": str(paper.id),
                                "title": paper.title,
                                "doi": paper.doi,
                                "published_at": str(paper.published_at) if paper.published_at else None,
                                "depth": len(reading_order),
                                "is_root": True,
                                "role": "target",
                            })

                            prereqs = [
                                {"id": str(p.id), "title": p.title, "reason": "semantically related, published earlier"}
                                for p in foundational[:5]
                            ]
                    except Exception:
                        pass

        return {
            "reading_order": reading_order,
            "prerequisites": prereqs,
        }

    async def _handle_search_with_reasoning(self, args: dict) -> dict:
        from app.services.search.instances import hybrid_service

        question = args["research_question"]
        scope = args.get("scope", "moderate")
        limit = args.get("limit", 10)

        search_query = self._extract_search_query(question)

        search_limit = {"narrow": limit, "moderate": limit * 2, "broad": limit * 3}[scope]
        results = hybrid_service.search(
            query=search_query,
            mode="hybrid",
            per_page=search_limit,
        )

        hits = results.get("hits", results.get("items", []))

        # Supplement with OpenAlex when local results are sparse
        external_hits = []
        if len(hits) < limit:
            try:
                from app.clients.openalex import OpenAlexClient
                oa = OpenAlexClient(mailto="kaleidoscope@research.app")
                try:
                    needed = limit - len(hits)
                    oa_results = await oa.search_works(search_query, rows=needed)
                    for work in oa_results:
                        title = work.get("title", "")
                        if not title:
                            continue
                        abstract_inv = work.get("abstract_inverted_index")
                        abstract = ""
                        if abstract_inv and isinstance(abstract_inv, dict):
                            words = sorted(
                                ((pos, word) for word, positions in abstract_inv.items() for pos in positions),
                                key=lambda x: x[0]
                            )
                            abstract = " ".join(w for _, w in words)[:300]
                        external_hits.append({
                            "title": title,
                            "abstract": abstract,
                            "year": work.get("publication_year"),
                            "citation_count": work.get("cited_by_count", 0),
                            "doi": work.get("doi", "").replace("https://doi.org/", "") if work.get("doi") else None,
                            "source": "openalex",
                        })
                finally:
                    await oa.close()
            except Exception:
                pass

        relevance_notes = []
        for hit in hits[:5]:
            pid = hit.get("id", "")
            title = hit.get("title", "")
            if title:
                relevance_notes.append({
                    "paper_id": pid,
                    "title": title,
                    "relevance_signal": f"Matched on: {title[:80]}",
                })

        result = {
            "papers": hits[:limit],
            "total_candidates": len(hits),
            "relevance_analysis": relevance_notes,
            "research_question": question,
            "search_mode": results.get("mode_used", "unknown"),
        }
        if external_hits:
            result["papers_external"] = external_hits
        return result

    async def _handle_build_evidence_map(self, args: dict) -> dict:
        from app.services.vector_search_service import VectorSearchService

        claim = args["claim_or_question"]
        paper_ids = args.get("paper_ids", [])
        top_k = args.get("top_k", 15)

        supporting = []
        qualifying = []
        weak = []

        # Primary: Qdrant paper-level semantic search (best scores)
        try:
            from app.services.search.instances import vector_service
            vec_results = vector_service.search(claim, top_k=top_k)
            seen_paper_ids = set()
            for hit in vec_results:
                pid = hit.get("paper_id", "")
                if not pid or (paper_ids and pid not in paper_ids):
                    continue
                if pid in seen_paper_ids:
                    continue
                seen_paper_ids.add(pid)
                score = hit.get("score", 0)
                title = hit.get("payload", {}).get("title", "") if hit.get("payload") else ""
                entry = {
                    "paper_id": pid,
                    "text": title,
                    "score": round(score, 4),
                    "section": "title+abstract (semantic)",
                    "title": title,
                }
                if score > 0.42:
                    supporting.append(entry)
                elif score > 0.30:
                    qualifying.append(entry)
                elif score > 0.20:
                    weak.append(entry)
        except Exception as e:
            logger.warning("evidence_map_qdrant_failed", error=str(e))

        # Secondary: pgvector chunk-level search (more granular evidence)
        svc = VectorSearchService(self.db)
        try:
            evidence = await svc.search_by_text(
                query_text=claim,
                paper_ids=paper_ids if paper_ids else None,
                top_k=top_k,
            )
            seen_chunks = set()
            for item in evidence:
                text = item.get("text", item.get("content", ""))
                score = item.get("score", item.get("similarity", 0))
                pid = item.get("paper_id", "")
                chunk_key = (pid, text[:100])
                if chunk_key in seen_chunks:
                    continue
                seen_chunks.add(chunk_key)
                entry = {
                    "paper_id": pid,
                    "text": text[:500],
                    "score": round(score, 4) if isinstance(score, float) else score,
                    "section": item.get("section", ""),
                }
                if score > 0.28:
                    supporting.append(entry)
                elif score > 0.20:
                    qualifying.append(entry)
        except Exception:
            pass

        # Keyword fallback when still sparse
        if not supporting and not qualifying:
            papers = await self._discover_relevant_papers(claim, limit=top_k)
            for p in papers:
                abstract = p.abstract or ""
                if not abstract:
                    continue
                claim_lower = claim.lower()
                keywords = [w for w in claim_lower.split() if len(w) > 3]
                matches = sum(1 for kw in keywords if kw in abstract.lower())
                relevance = matches / max(len(keywords), 1)
                entry = {
                    "paper_id": str(p.id),
                    "text": abstract[:500],
                    "score": round(relevance, 3),
                    "section": "abstract",
                    "title": p.title,
                }
                if relevance > 0.5:
                    supporting.append(entry)
                elif relevance > 0.25:
                    qualifying.append(entry)

        # Enrich with paper titles where missing
        missing_title_pids = [
            e["paper_id"] for e in supporting + qualifying
            if not e.get("title") and e.get("paper_id")
        ]
        if missing_title_pids:
            try:
                result = await self.db.execute(
                    select(Paper.id, Paper.title).where(Paper.id.in_(missing_title_pids[:20]))
                )
                title_map = {str(r.id): r.title for r in result.all()}
                for e in supporting + qualifying:
                    if not e.get("title") and e["paper_id"] in title_map:
                        e["title"] = title_map[e["paper_id"]]
            except Exception:
                pass

        # Always supplement with external evidence from OpenAlex for broader context
        external_evidence = []
        try:
            from app.clients.openalex import OpenAlexClient
            oa = OpenAlexClient(mailto="kaleidoscope@research.app")
            try:
                oa_results = await oa.search_works(claim, rows=8)
                for work in oa_results:
                    title = work.get("title", "")
                    abstract_inv = work.get("abstract_inverted_index")
                    abstract = ""
                    if abstract_inv and isinstance(abstract_inv, dict):
                        words = sorted(
                            ((pos, word) for word, positions in abstract_inv.items() for pos in positions),
                            key=lambda x: x[0]
                        )
                        abstract = " ".join(w for _, w in words)[:400]
                    if title:
                        external_evidence.append({
                            "title": title,
                            "text": abstract or title,
                            "year": work.get("publication_year"),
                            "citation_count": work.get("cited_by_count", 0),
                            "doi": work.get("doi", "").replace("https://doi.org/", "") if work.get("doi") else None,
                            "source": "openalex",
                        })
            finally:
                await oa.close()
        except Exception:
            pass

        return {
            "claim": claim,
            "supporting_evidence": supporting,
            "qualifying_evidence": qualifying,
            "weak_evidence": weak,
            "external_evidence": external_evidence,
            "total_evidence_items": len(supporting) + len(qualifying) + len(weak) + len(external_evidence),
            "paper_ids_searched": paper_ids,
        }

