    # ─── Topic Monitor Tools ─────────────────────────────────────────────

    async def _handle_topic_monitor_create(self, args: dict) -> dict:
        """Create a living topic monitor for a dossier."""
        from app.services.topic_monitor_service import TopicMonitorService

        dossier_id = args.get("dossier_id")
        if not dossier_id:
            return {"error": "dossier_id is required"}

        service = TopicMonitorService(self.db)
        # Get topic from dossier if not provided
        topic = args.get("topic")
        if not topic:
            from sqlalchemy import text as sql_text
            result = await self.db.execute(sql_text(
                "SELECT topic FROM research_dossiers WHERE id = :id"
            ), {"id": dossier_id})
            row = result.fetchone()
            topic = row[0] if row else "unknown"

        return await service.create_monitor(
            dossier_id=dossier_id,
            topic=topic,
            cadence=args.get("cadence", "daily"),
            query_config=args.get("query_config"),
        )

    async def _handle_topic_monitor_run(self, args: dict) -> dict:
        """Run one monitoring cycle immediately."""
        from app.services.topic_monitor_service import TopicMonitorService

        service = TopicMonitorService(self.db)
        return await service.run_monitor(
            monitor_id=args.get("monitor_id"),
            dossier_id=args.get("dossier_id"),
            lookback_days=min(max(args.get("lookback_days", 30), 1), 90),
            max_papers=min(max(args.get("max_papers", 20), 5), 50),
        )

    async def _handle_topic_monitor_digest(self, args: dict) -> dict:
        """Get a compact 'what changed' report."""
        from app.services.topic_monitor_service import TopicMonitorService

        dossier_id = args.get("dossier_id")
        if not dossier_id:
            return {"error": "dossier_id is required"}

        service = TopicMonitorService(self.db)
        return await service.get_digest(
            dossier_id=dossier_id,
            since=args.get("since"),
        )

    # ─── Research Synthesis ──────────────────────────────────────────────

    async def _handle_research_synthesis(self, args: dict) -> dict:
        """Synthesize research from multiple dossiers into a structured narrative."""
        from sqlalchemy import text as sql_text
        from app.clients.llm_client import LLMClient, DEFAULT_CHAT_MODEL
        from app.services.claim_ledger_service import ClaimLedgerService

        dossier_ids = args.get("dossier_ids", [])
        if not dossier_ids:
            return {"error": "dossier_ids is required (list of UUIDs)"}

        focus = args.get("focus", "comprehensive")
        max_length = min(max(args.get("max_length", 3000), 1000), 10000)

        # Load all dossiers
        dossiers_data = []
        for did in dossier_ids:
            result = await self.db.execute(sql_text("""
                SELECT topic, research_question, status, papers_seen, claims,
                       gaps, decisions, open_questions, coverage_score
                FROM research_dossiers
                WHERE id = :id AND deleted_at IS NULL
            """), {"id": did})
            row = result.fetchone()
            if row:
                dossiers_data.append({
                    "id": did,
                    "topic": row[0],
                    "research_question": row[1],
                    "status": row[2],
                    "papers_seen": row[3] or {},
                    "claims": row[4] or {},
                    "gaps": row[5] or {},
                    "decisions": row[6] or {},
                    "open_questions": row[7] or [],
                    "coverage_score": row[8],
                })

        if not dossiers_data:
            return {"error": "No valid dossiers found"}

        topic = args.get("topic") or " + ".join(d["topic"] for d in dossiers_data)

        # Gather claims from the global ledger for these dossiers
        ledger = ClaimLedgerService(self.db)
        all_claims = []
        disputed_claims = []
        for did in dossier_ids:
            graph = await ledger.get_claim_graph(did)
            for node in graph.get("nodes", []):
                claim_entry = {
                    "text": node["text"],
                    "status": node["status"],
                    "support_count": node["support_count"],
                    "contradict_count": node["contradict_count"],
                    "dossier_id": did,
                }
                all_claims.append(claim_entry)
                if node["status"] == "disputed":
                    disputed_claims.append(claim_entry)

        # Also gather dossier-level claims
        for d in dossiers_data:
            for key, claim in d["claims"].items():
                all_claims.append({
                    "text": claim.get("text", key),
                    "verdict": claim.get("verdict"),
                    "confidence": claim.get("confidence"),
                    "dossier_id": d["id"],
                })

        # Build synthesis prompt
        total_papers = sum(len(d["papers_seen"]) for d in dossiers_data)
        all_gaps = []
        for d in dossiers_data:
            for key, gap in d["gaps"].items():
                all_gaps.append(gap.get("description", key))

        # Construct evidence block for LLM
        evidence_block = f"Topic: {topic}\n"
        evidence_block += f"Dossiers: {len(dossiers_data)} | Papers: {total_papers} | Claims: {len(all_claims)}\n\n"

        evidence_block += "KEY CLAIMS:\n"
        for i, c in enumerate(all_claims[:20], 1):
            status_tag = f"[{c.get('status', c.get('verdict', '?'))}]" if c.get("status") or c.get("verdict") else ""
            evidence_block += f"{i}. {status_tag} {c['text'][:150]}\n"

        if disputed_claims:
            evidence_block += f"\nDISPUTED CLAIMS ({len(disputed_claims)}):\n"
            for dc in disputed_claims[:5]:
                evidence_block += f"- {dc['text'][:120]} (contradictions: {dc['contradict_count']})\n"

        if all_gaps:
            evidence_block += f"\nKNOWLEDGE GAPS:\n"
            for g in all_gaps[:8]:
                evidence_block += f"- {g}\n"

        focus_instruction = {
            "comprehensive": "Cover all major findings, methods, and gaps. Balance breadth with depth.",
            "consensus": "Focus on claims with strong support across multiple papers. Highlight agreement.",
            "disputes": "Focus on contradictions and disputed claims. Explain both sides.",
            "gaps": "Focus on what's missing. Identify under-researched areas and open questions.",
            "methods": "Focus on methodological approaches. Compare and contrast techniques.",
        }.get(focus, "Provide a comprehensive synthesis.")

        prompt = (
            f"Synthesize the following research evidence into a structured narrative.\n\n"
            f"EVIDENCE:\n{evidence_block}\n\n"
            f"FOCUS: {focus_instruction}\n\n"
            f"Write a structured research synthesis (~{max_length} chars). Use these sections:\n"
            f"1. Overview (2-3 sentences)\n"
            f"2. Key Findings (organized by theme)\n"
            f"3. {'Disputes & Contradictions' if focus in ('disputes', 'comprehensive') else 'Consensus'}\n"
            f"4. Gaps & Open Questions\n"
            f"5. Implications & Next Steps\n\n"
            f"Be specific. Cite claim numbers [1], [2] etc. No filler."
        )

        llm = LLMClient()
        try:
            synthesis = await llm.complete(
                prompt=prompt,
                system="You are a research synthesis expert. Write clear, structured academic prose. Be precise and evidence-based.",
                model=DEFAULT_CHAT_MODEL,
                max_tokens=max_length // 3,
                temperature=0.3,
            )
        except Exception as e:
            synthesis = f"Synthesis generation failed: {str(e)[:100]}"
        finally:
            await llm.close()

        return {
            "topic": topic,
            "focus": focus,
            "dossiers_used": len(dossiers_data),
            "total_papers": total_papers,
            "total_claims": len(all_claims),
            "disputed_claims": len(disputed_claims),
            "gaps_identified": len(all_gaps),
            "synthesis": synthesis,
            "metadata": {
                "dossier_ids": dossier_ids,
                "coverage_scores": {d["id"]: d["coverage_score"] for d in dossiers_data if d["coverage_score"]},
            },
        }

    # ─── Smart Search ────────────────────────────────────────────────────

    async def _handle_smart_search(self, args: dict) -> dict:
        """Intelligent search with claim-graph query expansion."""
        from app.services.claim_ledger_service import ClaimLedgerService

        query = args.get("query", "")
        if not query:
            return {"error": "query is required"}

        max_results = min(max(args.get("max_results", 15), 5), 30)
        expand_from_claims = args.get("expand_from_claims", True)

        results_by_strategy = {}
        seen_paper_ids = set()

        # Strategy 1: Direct search (baseline)
        direct_results = await self._handle_search_papers({
            "query": query,
            "limit": max_results // 2,
            "search_type": "hybrid",
        })
        direct_hits = direct_results.get("hits", []) or direct_results.get("results", [])
        for hit in direct_hits:
            pid = hit.get("paper_id", hit.get("id", ""))
            if pid:
                seen_paper_ids.add(pid)
        results_by_strategy["direct"] = {
            "query": query,
            "hits": direct_hits[:max_results // 2],
        }

        # Strategy 2: Claim-graph expansion
        expanded_hits = []
        expansion_queries = []
        if expand_from_claims:
            ledger = ClaimLedgerService(self.db)
            claim_results = await ledger.search_claims(query, limit=5)
            related_claims = claim_results.get("claims", [])

            # Extract key terms from related claims
            for claim in related_claims[:3]:
                claim_text = claim.get("canonical_text", "")
                # Extract meaningful phrases (skip common words)
                words = claim_text.lower().split()
                stop_words = {"the", "a", "an", "is", "are", "was", "were", "in", "on", "at",
                              "to", "for", "of", "with", "that", "this", "from", "by", "we",
                              "our", "and", "or", "not", "it", "its", "has", "have", "been"}
                key_terms = [w for w in words if w not in stop_words and len(w) > 3][:6]
                if key_terms:
                    expansion_query = " ".join(key_terms[:4])
                    if expansion_query != query.lower() and expansion_query not in expansion_queries:
                        expansion_queries.append(expansion_query)

            # Run expanded searches
            for eq in expansion_queries[:2]:
                try:
                    exp_results = await self._handle_search_papers({
                        "query": eq,
                        "limit": 5,
                        "search_type": "hybrid",
                    })
                    exp_hits = exp_results.get("hits", []) or exp_results.get("results", [])
                    for hit in exp_hits:
                        pid = hit.get("paper_id", hit.get("id", ""))
                        if pid and pid not in seen_paper_ids:
                            seen_paper_ids.add(pid)
                            expanded_hits.append(hit)
                except Exception:
                    pass

        if expanded_hits:
            results_by_strategy["claim_expansion"] = {
                "expansion_queries": expansion_queries,
                "hits": expanded_hits[:max_results // 3],
            }

        # Strategy 3: Dossier-context expansion (if dossier_id provided)
        dossier_hits = []
        if args.get("dossier_id"):
            try:
                from sqlalchemy import text as sql_text
                result = await self.db.execute(sql_text("""
                    SELECT open_questions, gaps FROM research_dossiers
                    WHERE id = :id AND deleted_at IS NULL
                """), {"id": args["dossier_id"]})
                row = result.fetchone()
                if row:
                    questions = row[0] or []
                    gaps = row[1] or {}
                    # Use first open question as expansion
                    for q in questions[:1]:
                        if isinstance(q, str) and len(q) > 10:
                            q_results = await self._handle_search_papers({
                                "query": q[:80],
                                "limit": 5,
                                "search_type": "hybrid",
                            })
                            q_hits = q_results.get("hits", []) or q_results.get("results", [])
                            for hit in q_hits:
                                pid = hit.get("paper_id", hit.get("id", ""))
                                if pid and pid not in seen_paper_ids:
                                    seen_paper_ids.add(pid)
                                    dossier_hits.append(hit)
            except Exception:
                pass

        if dossier_hits:
            results_by_strategy["dossier_context"] = {
                "hits": dossier_hits[:5],
            }

        # Combine all results
        all_hits = direct_hits[:max_results // 2]
        all_hits.extend(expanded_hits[:max_results // 3])
        all_hits.extend(dossier_hits[:5])

        return {
            "query": query,
            "total_results": len(all_hits),
            "strategies_used": list(results_by_strategy.keys()),
            "expansion_queries": expansion_queries,
            "results": all_hits[:max_results],
            "results_by_strategy": results_by_strategy,
        }

    # ─── Hypothesis Generator ────────────────────────────────────────────

    async def _handle_hypothesis_generator(self, args: dict) -> dict:
        """Generate testable research hypotheses from dossier knowledge."""
        from sqlalchemy import text as sql_text
        from app.clients.llm_client import LLMClient, DEFAULT_CHAT_MODEL
        from app.services.claim_ledger_service import ClaimLedgerService

        dossier_id = args.get("dossier_id")
        if not dossier_id:
            return {"error": "dossier_id is required"}

        num_hypotheses = min(max(args.get("num_hypotheses", 3), 1), 5)
        style = args.get("style", "exploratory")
        focus_area = args.get("focus_area", "")

        # Load dossier
        result = await self.db.execute(sql_text("""
            SELECT topic, research_question, claims, gaps, open_questions,
                   papers_seen, coverage_score
            FROM research_dossiers
            WHERE id = :id AND deleted_at IS NULL
        """), {"id": dossier_id})
        row = result.fetchone()
        if not row:
            return {"error": f"Dossier not found: {dossier_id}"}

        topic, rq, claims, gaps, open_questions, papers_seen, coverage_score = row
        claims = claims or {}
        gaps = gaps or {}
        open_questions = open_questions or []
        papers_seen = papers_seen or {}

        # Get disputed claims from ledger
        ledger = ClaimLedgerService(self.db)
        graph = await ledger.get_claim_graph(dossier_id)
        disputed = [n for n in graph.get("nodes", []) if n.get("status") == "disputed"]

        # Build context for LLM
        context = f"RESEARCH TOPIC: {topic}\n"
        if rq:
            context += f"RESEARCH QUESTION: {rq}\n"
        if focus_area:
            context += f"FOCUS AREA: {focus_area}\n"
        context += f"PAPERS REVIEWED: {len(papers_seen)}\n"
        if coverage_score:
            context += f"COVERAGE SCORE: {coverage_score}/100\n"

        context += "\nESTABLISHED CLAIMS:\n"
        for key, claim in list(claims.items())[:10]:
            verdict = claim.get("verdict", "?")
            context += f"- [{verdict}] {claim.get('text', key)[:120]}\n"

        if disputed:
            context += f"\nDISPUTED CLAIMS ({len(disputed)}):\n"
            for d in disputed[:5]:
                context += f"- {d['text'][:120]} (contradictions: {d['contradict_count']})\n"

        if gaps:
            context += "\nKNOWLEDGE GAPS:\n"
            for key, gap in list(gaps.items())[:6]:
                context += f"- {gap.get('description', key)}\n"

        if open_questions:
            context += "\nOPEN QUESTIONS:\n"
            for q in open_questions[:5]:
                context += f"- {q}\n"

        style_instruction = {
            "exploratory": "Generate novel hypotheses that explore uncharted territory. Focus on gaps and unexplored connections.",
            "confirmatory": "Generate hypotheses that would strengthen or validate existing claims with new evidence or methods.",
            "contradictory": "Generate hypotheses that challenge existing assumptions or disputed claims. Look for potential flaws.",
        }.get(style, "Generate exploratory hypotheses.")

        prompt = (
            f"{context}\n\n"
            f"TASK: Generate {num_hypotheses} testable research hypotheses.\n"
            f"STYLE: {style_instruction}\n\n"
            f"For each hypothesis, provide:\n"
            f"1. hypothesis: A clear, falsifiable statement\n"
            f"2. rationale: Why this is worth testing (2-3 sentences)\n"
            f"3. methodology: Suggested approach to test it (1-2 sentences)\n"
            f"4. expected_impact: What would change if confirmed (1 sentence)\n"
            f"5. confidence: How likely this is novel/untested (low/medium/high)\n\n"
            f"Return ONLY a JSON array of objects with these fields."
        )

        llm = LLMClient()
        try:
            raw = await llm.complete(
                prompt=prompt,
                system="You are a research hypothesis generator. Produce specific, testable, novel hypotheses grounded in the evidence. Return valid JSON only.",
                model=DEFAULT_CHAT_MODEL,
                max_tokens=2000,
                temperature=0.4,
            )
            hypotheses = self._extract_json(raw)
            if not isinstance(hypotheses, list):
                hypotheses = [hypotheses] if isinstance(hypotheses, dict) else []
        except Exception as e:
            hypotheses = [{"hypothesis": f"Generation failed: {str(e)[:80]}", "rationale": "", "methodology": "", "expected_impact": "", "confidence": "low"}]
        finally:
            await llm.close()

        return {
            "dossier_id": dossier_id,
            "topic": topic,
            "style": style,
            "focus_area": focus_area or None,
            "hypotheses": hypotheses[:num_hypotheses],
            "context_used": {
                "claims": len(claims),
                "disputed_claims": len(disputed),
                "gaps": len(gaps),
                "open_questions": len(open_questions),
                "papers": len(papers_seen),
            },
        }

