    # --- Research Memory handlers ---

    async def _handle_memory_store(self, args: dict) -> dict:
        """Store research insight."""
        from app.services.research_memory_service import ResearchMemoryService

        insight = args.get("insight", "")
        if not insight:
            return {"error": "insight is required"}

        service = ResearchMemoryService(self.db)
        return await service.store_insight(
            insight,
            domain=args.get("domain", ""),
            confidence=args.get("confidence", 0.5),
            source_tools=args.get("source_tools"),
            question=args.get("question", ""),
            tags=args.get("tags"),
        )

    async def _handle_memory_recall(self, args: dict) -> dict:
        """Recall from research memory."""
        from app.services.research_memory_service import ResearchMemoryService

        query = args.get("query", "")
        if not query:
            return {"error": "query is required"}

        service = ResearchMemoryService(self.db)
        return await service.recall(
            query,
            domain=args.get("domain", ""),
            limit=args.get("limit", 10),
        )

    async def _handle_memory_summarize(self, args: dict) -> dict:
        """Summarize research memory."""
        from app.services.research_memory_service import ResearchMemoryService

        service = ResearchMemoryService(self.db)
        return await service.summarize_memory(
            domain=args.get("domain", ""),
        )

